namespace PZ3D {
 static class InstallerShortcutTests {
  static int passed;
  static string boundary,captures;
  static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
  static T Find<T>(Form form,string name)where T:Control{return (T)form.Controls.Find(name,true).Single();}
  static string Fresh(string name){return Path.Combine(boundary,name+"-"+Guid.NewGuid().ToString("N").Substring(0,8));}
  static void Pump(Func<bool> done){var until=DateTime.UtcNow.AddSeconds(12);while(!done()){if(DateTime.UtcNow>until)throw new Exception("UI deadline");Application.DoEvents();Thread.Sleep(10);}Application.DoEvents();}
  static void Capture(Form form,string name){Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(Path.Combine(captures,name+".png"));}}
  static void ScaleFonts(Control control){foreach(Control child in control.Controls)ScaleFonts(child);control.Font=new Font(control.Font.FontFamily,control.Font.SizeInPoints*1.5f,control.Font.Style);}
  static void Ui(){
   foreach(string mode in new[]{"checked","unchecked","failure","shortcut-error"}){
    int calls=0,opens=0,uiThread=Thread.CurrentThread.ManagedThreadId;InstallerInstallResult exact=null;
    using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim())using(var form=new InstallerForm(new InstallerDestination{Root=Fresh("ui")},(root,p)=>{entered.Set();if(!release.Wait(8000))throw new Exception("UI fixture deadline");if(mode=="failure")throw new IOException("fixture install failure");return exact=new InstallerInstallResult(root,AppVersion.Current,"fixture");},r=>{Check(object.ReferenceEquals(r,exact),"open keeps exact installed result after shortcut outcome");opens++;},r=>{Check(object.ReferenceEquals(r,exact)&&Thread.CurrentThread.ManagedThreadId!=uiThread,"shortcut boundary receives exact result off UI thread");calls++;return mode=="shortcut-error"?new InstallerShortcutResult(false,"","fixture desktop denied"):new InstallerShortcutResult(true,"fixture desktop/link.lnk","fixture shortcut created");})){
     try{form.Show();var option=Find<CheckBox>(form,"installer-desktop-shortcut");Check(option.Checked&&calls==0,"opening installer is read-only with default checked option");if(mode=="unchecked")option.Checked=false;if(mode=="checked")Capture(form,"shortcut-ready-normal");Find<Button>(form,"installer-install").PerformClick();Pump(()=>entered.IsSet);Check(!option.Enabled,"shortcut option disabled during installation");if(mode=="checked")option.Checked=false;release.Set();Pump(()=>Find<Button>(form,"installer-finish").Visible);
      Check(calls==((mode=="unchecked"||mode=="failure")?0:1),"captured shortcut choice invokes boundary once only after successful "+mode+" install");
      if(mode=="failure")Check(form.ExitCode==1&&!Find<Button>(form,"installer-open").Visible,"install failure cannot expose Open or create shortcut");
      else{Check(form.ExitCode==0&&Find<Button>(form,"installer-open").Visible,"shortcut outcome preserves successful installation and Open");if(mode=="shortcut-error"){Check(Find<Label>(form,"installer-shortcut-outcome").Text.Contains("fixture desktop denied")&&Find<TextBox>(form,"installer-details").Text.Contains("fixture desktop denied"),"shortcut warning visible and copyable independent of install success");Capture(form,"shortcut-warning-normal");}Find<Button>(form,"installer-open").PerformClick();Check(opens==1,"Open remains explicitly usable after "+mode);}
      if(mode=="checked"){Check(Find<TextBox>(form,"installer-details").Text.Contains("fixture desktop/link.lnk"),"created shortcut path included in details");Capture(form,"shortcut-complete-normal");}form.Close();
     }finally{release.Set();}
    }
   }
   using(var form=new InstallerForm(new InstallerDestination{Root=Fresh("layout")},(root,p)=>new InstallerInstallResult(root,AppVersion.Current,"fixture"),r=>{})){
    form.ClientSize=new Size(520,420);form.Show();Capture(form,"shortcut-ready-small");Check(Find<CheckBox>(form,"installer-desktop-shortcut").Width>200,"small layout retains usable shortcut option");form.AutoScaleMode=AutoScaleMode.None;form.Scale(new SizeF(1.5f,1.5f));ScaleFonts(form);form.ClientSize=new Size(780,630);Capture(form,"shortcut-ready-scaled-150");form.Close();
   }
  }
  sealed class Fixture {
   internal string Root,Desktop;internal InstallerInstallResult Result;internal InstallerShortcut Service;
   internal Fixture(){Root=Fresh("installed");Desktop=Fresh("OneDrive-redirected-Desktop");Directory.CreateDirectory(Desktop);var files=new Dictionary<string,byte[]>(CoreFixture.A){{"卸载橙子启动器.exe",CoreFixture.Bytes("fixture uninstaller")}};var record=CoreDeployment.Install(Root,CoreFixture.Manifest("1.2.3",files),files,CoreFixture.Key);Result=new InstallerInstallResult(Root,"1.2.3",record.installationId);Service=new InstallerShortcut(()=>Desktop,CoreFixture.Key);}
   internal string Receipt{get{return Path.Combine(Root,InstallerShortcut.Receipt.Replace('/',Path.DirectorySeparatorChar));}}
  }
  static void Service(){
   var fixture=new Fixture();var made=fixture.Service.CreateOwned(fixture.Result);Check(made.Created&&Path.GetDirectoryName(made.Path)==fixture.Desktop&&File.Exists(fixture.Receipt),"real shell COM creates direct-child link in selected redirected fixture desktop and receipt");var parsed=InstallerShortcut.ReadLink(made.Path);
   Check(parsed.Target==Path.Combine(fixture.Root,"橙子启动器.exe")&&parsed.WorkingDirectory==fixture.Root&&parsed.Arguments==""&&parsed.Icon==Path.Combine(fixture.Root,"橙子启动器.exe")+",0","real .lnk parsing confirms exact target, workdir, empty arguments and EXE icon without launching");
   Check(!fixture.Service.CreateOwned(fixture.Result).Created&&Directory.GetFiles(fixture.Desktop).Length==1,"existing receipt prevents duplicate shortcut creation");Check(fixture.Service.Remove(fixture.Root).Contains("已删除")&&!File.Exists(made.Path),"only exact owned link deleted while authenticated identity remains");
   var conflict=new Fixture();string occupied=Path.Combine(conflict.Desktop,"橙子启动器.lnk");File.WriteAllText(occupied,"foreign");var second=conflict.Service.CreateOwned(conflict.Result);Check(second.Created&&Path.GetFileName(second.Path)=="橙子启动器 (2).lnk"&&File.ReadAllText(occupied)=="foreign","same-name conflict chooses bounded suffix without overwriting");
   var full=new Fixture();for(int n=1;n<=100;n++)File.WriteAllText(Path.Combine(full.Desktop,n==1?"橙子启动器.lnk":"橙子启动器 ("+n+").lnk"),"foreign");Check(!full.Service.CreateOwned(full.Result).Created&&Directory.GetFiles(full.Desktop).Length==100&&!File.Exists(full.Receipt),"100 occupied names exhaust bounded search without side effects");
   foreach(string damage in new[]{"source","record","identity","result-path"}){var f=new Fixture();if(damage=="source")File.WriteAllText(f.Result.LauncherPath,"tampered");if(damage=="record")File.WriteAllText(Path.Combine(f.Root,CoreDeployment.RecordName),"{}");var result=damage=="identity"?new InstallerInstallResult(f.Root,"1.2.3",Guid.NewGuid().ToString("N")):damage=="result-path"?new InstallerInstallResult(Fresh("foreign-root"),"1.2.3",f.Result.InstallationId):f.Result;Check(!f.Service.CreateOwned(result).Created&&Directory.GetFiles(f.Desktop).Length==0,"unauthenticated "+damage+" refuses desktop write");}
   var denied=new Fixture();var broken=new InstallerShortcut(()=>denied.Desktop,CoreFixture.Key,(path,link)=>{throw new UnauthorizedAccessException("fixture unwritable desktop");});Check(!broken.CreateOwned(denied.Result).Created&&File.Exists(denied.Result.LauncherPath)&&Directory.GetFiles(denied.Desktop).Length==0,"COM/write failure is independent warning and retains installed files");
   var partial=new Fixture();var partialWriter=new InstallerShortcut(()=>partial.Desktop,CoreFixture.Key,(path,link)=>{File.WriteAllText(path,"partial fixture");throw new IOException("fixture partial write failure");});Check(!partialWriter.CreateOwned(partial.Result).Created&&Directory.GetFiles(partial.Desktop).Length==1&&!File.Exists(partial.Receipt),"partial I/O failure stops after one unclaimed file instead of filling all 100 collision names");
   var badDestination=new Fixture();string blocked=Path.Combine(badDestination.Desktop,"file");File.WriteAllText(blocked,"keep");Check(!new InstallerShortcut(()=>blocked,CoreFixture.Key).CreateOwned(badDestination.Result).Created&&File.ReadAllText(blocked)=="keep","unwritable or invalid desktop destination preserves installation and foreign file");
   var aclFixture=new Fixture();var originalAcl=Directory.GetAccessControl(aclFixture.Desktop,AccessControlSections.Access);byte[] originalDescriptor=originalAcl.GetSecurityDescriptorBinaryForm();try{var deniedAcl=new DirectorySecurity();deniedAcl.SetSecurityDescriptorBinaryForm(originalDescriptor,AccessControlSections.Access);using(var identity=WindowsIdentity.GetCurrent())deniedAcl.AddAccessRule(new FileSystemAccessRule(identity.User,FileSystemRights.CreateFiles,AccessControlType.Deny));Directory.SetAccessControl(aclFixture.Desktop,deniedAcl);var refused=aclFixture.Service.CreateOwned(aclFixture.Result);Check(!refused.Created&&File.Exists(aclFixture.Result.LauncherPath)&&Directory.GetFiles(aclFixture.Desktop).Length==0,"real fixture desktop ACL denial reports warning without reinstalling or deleting program");}finally{var restore=new DirectorySecurity();restore.SetSecurityDescriptorBinaryForm(originalDescriptor,AccessControlSections.Access);Directory.SetAccessControl(aclFixture.Desktop,restore);}
   var mta=new Fixture();var fromWorker=System.Threading.Tasks.Task.Run(()=>mta.Service.CreateOwned(mta.Result)).Result;Check(fromWorker.Created&&InstallerShortcut.ReadLink(fromWorker.Path).Target==mta.Result.LauncherPath,"real shell service marshals MTA installer worker to STA without launching target");
   var changedDuringCreate=new Fixture();var changedWriter=new InstallerShortcut(()=>changedDuringCreate.Desktop,CoreFixture.Key,(path,link)=>{return InstallerShortcut.WriteLink(path,new InstallerShortcutLink{Target=changedDuringCreate.Result.UninstallerPath,WorkingDirectory=changedDuringCreate.Root,Arguments="",Icon=changedDuringCreate.Result.UninstallerPath+",0"});});Check(!changedWriter.CreateOwned(changedDuringCreate.Result).Created&&!File.Exists(changedDuringCreate.Receipt)&&Directory.GetFiles(changedDuringCreate.Desktop).Length==1,"changed link during creation is left unclaimed and never removed as external content");
   var alteredBytes=new Fixture();var byteWriter=new InstallerShortcut(()=>alteredBytes.Desktop,CoreFixture.Key,(path,link)=>{string hash=InstallerShortcut.WriteLink(path,link);File.AppendAllText(path,"external bytes");return hash;});Check(!byteWriter.CreateOwned(alteredBytes.Result).Created&&!File.Exists(alteredBytes.Receipt),"replacement bytes during creation cannot earn a receipt even when parsed target fields still match");
   foreach(string damage in new[]{"hash","unknown","unknown-field","duplicate-field","malformed","large","path","id","target","arguments","icon","workdir"}){
    var f=new Fixture();var created=f.Service.CreateOwned(f.Result);string original=File.ReadAllText(f.Receipt);
    if(damage=="hash")File.AppendAllText(created.Path,"user edit");
    else if(damage=="malformed")File.WriteAllText(f.Receipt,"{");
    else if(damage=="large")File.WriteAllText(f.Receipt,new string('x',17000));
    else if(damage=="unknown")File.WriteAllText(f.Receipt,original.Replace("\"schema\":1","\"schema\":99"));
    else if(damage=="unknown-field")File.WriteAllText(f.Receipt,original.Replace("\"schema\":1","\"schema\":1,\"untrusted\":true"));
    else if(damage=="duplicate-field")File.WriteAllText(f.Receipt,original.Replace("\"schema\":1","\"schema\":99,\"schema\":1"));
    else if(damage=="id")File.WriteAllText(f.Receipt,original.Replace(f.Result.InstallationId,Guid.NewGuid().ToString("N")));
    else if(damage=="path")File.WriteAllText(f.Receipt,original.Replace("橙子启动器.lnk","foreign.lnk"));
    else {var link=InstallerShortcut.ReadLink(created.Path);if(damage=="target")link.Target=Path.Combine(f.Root,"卸载橙子启动器.exe");if(damage=="arguments")link.Arguments="--foreign";if(damage=="icon")link.Icon=Path.Combine(f.Root,"卸载橙子启动器.exe")+",0";if(damage=="workdir")link.WorkingDirectory=f.Desktop;File.Delete(created.Path);InstallerShortcut.WriteLink(created.Path,link);var receipt=CoreDeployment.Json.Deserialize<Dictionary<string,object>>(original);receipt["sha256"]=CoreReleaseProtocol.HashFile(created.Path);File.WriteAllText(f.Receipt,CoreDeployment.Json.Serialize(receipt));}
    string warning=f.Service.Remove(f.Root);Check(File.Exists(created.Path)&&warning.Contains("保留"),"changed "+damage+" ownership or parsed shell data preserves link with warning");
   }
   var foreign=new Fixture();var own=foreign.Service.CreateOwned(foreign.Result);File.Delete(own.Path);File.Copy(second.Path,own.Path);Check(foreign.Service.Remove(foreign.Root).Contains("保留")&&File.Exists(own.Path),"foreign replacement link is preserved");
   var missing=new Fixture();Check(missing.Service.Remove(missing.Root)==""&&Directory.GetFiles(missing.Desktop).Length==0,"absent receipt is read-only no-op");
   var moved=new Fixture();var movedLink=moved.Service.CreateOwned(moved.Result);string differentDesktop=Fresh("different-desktop");Directory.CreateDirectory(differentDesktop);Check(new InstallerShortcut(()=>differentDesktop,CoreFixture.Key).Remove(moved.Root).Contains("保留")&&File.Exists(movedLink.Path),"receipt outside current known desktop is preserved after desktop selection changes");
   var lockedLink=new Fixture();var lockedMade=lockedLink.Service.CreateOwned(lockedLink.Result);using(var held=new FileStream(lockedMade.Path,FileMode.Open,FileAccess.Read,FileShare.Read)){Check(lockedLink.Service.Remove(lockedLink.Root).Contains("保留")&&File.Exists(lockedMade.Path),"locked desktop file returns independent cleanup warning without path deletion");}
   var upgraded=new Fixture();var old=upgraded.Service.CreateOwned(upgraded.Result);var next=new Dictionary<string,byte[]>(CoreFixture.A){{"卸载橙子启动器.exe",CoreFixture.Bytes("fixture uninstaller")}};next["橙子启动器.exe"]=CoreFixture.Bytes("signed upgraded launcher");string task=CoreUpdateTransaction.Stage(upgraded.Root,CoreFixture.Manifest("1.2.4",next),new Dictionary<string,byte[]>{{"橙子启动器.exe",next["橙子启动器.exe"]}},CoreFixture.Key);CoreUpdateTransaction.Apply(upgraded.Root,task,exe=>true,null,CoreFixture.Key);Check(CoreDeployment.ReadAuthenticated(upgraded.Root,CoreFixture.Key).installationId==upgraded.Result.InstallationId&&upgraded.Service.Remove(upgraded.Root).Contains("已删除")&&!File.Exists(old.Path),"signed same-installation upgrade changing version and launcher hash retains valid cleanup ownership");
   var changedId=new Fixture();var retained=changedId.Service.CreateOwned(changedId.Result);string newId=Guid.NewGuid().ToString("N");File.WriteAllText(Path.Combine(changedId.Root,CoreDeployment.Owner.Replace('/',Path.DirectorySeparatorChar)),newId);string recordPath=Path.Combine(changedId.Root,CoreDeployment.RecordName);File.WriteAllText(recordPath,File.ReadAllText(recordPath).Replace(changedId.Result.InstallationId,newId));Check(changedId.Service.Remove(changedId.Root).Contains("保留")&&File.Exists(retained.Path),"different authenticated installationId refuses old receipt cleanup");
   var warningFixture=new Fixture();var warned=warningFixture.Service.CreateOwned(warningFixture.Result);File.AppendAllText(warned.Path,"user change");bool warningScheduled=false;string uninstallWarning=UninstallerProgram.UninstallCore(warningFixture.Root,warningFixture.Result.UninstallerPath,CoreFixture.Key,warningFixture.Service.Remove,()=>warningScheduled=true);Check(warningScheduled&&uninstallWarning.Contains("桌面快捷方式保留")&&File.Exists(warned.Path)&&File.ReadAllText(Path.Combine(warningFixture.Root,CoreDeployment.Runtime,"desktop-shortcut-uninstall.log")).Contains("保留"),"cleanup warning appended to successful uninstall outcome and runtime diagnostics while edited link remains");
   Reparse();Uninstall();
   Check(Directory.GetFiles(boundary,"*.lnk",SearchOption.TopDirectoryOnly).Length==0,"all links stay in fixture desktops, no launch boundary invoked by shortcut service");
  }
  static void Junction(string link,string target){using(var process=Process.Start(new ProcessStartInfo("cmd.exe","/c mklink /J \""+link+"\" \""+target+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){process.StandardOutput.ReadToEnd();string error=process.StandardError.ReadToEnd();process.WaitForExit();if(process.ExitCode!=0)throw new Exception("fixture junction: "+error);}}
  static void Reparse(){var f=new Fixture();string link=Fresh("desktop-junction");Junction(link,f.Desktop);Check(!new InstallerShortcut(()=>link,CoreFixture.Key).CreateOwned(f.Result).Created&&Directory.GetFiles(f.Desktop).Length==0,"reparse desktop ancestor refused without following target");var made=f.Service.CreateOwned(f.Result);File.Delete(made.Path);Junction(made.Path,f.Desktop);Check(f.Service.Remove(f.Root).Contains("保留")&&Directory.Exists(made.Path),"reparse link replacement preserved without traversing it");var r=new Fixture();var own=r.Service.CreateOwned(r.Result);File.Delete(r.Receipt);Junction(r.Receipt,r.Desktop);Check(r.Service.Remove(r.Root).Contains("保留")&&File.Exists(own.Path),"reparse receipt refused without deleting desktop link");}
  static void Uninstall(){
   foreach(string kind in new[]{"modified","locked","pending","success"}){var f=new Fixture();var created=f.Service.CreateOwned(f.Result);bool scheduled=false;string warning="";Action uninstall=()=>warning=UninstallerProgram.UninstallCore(f.Root,f.Result.UninstallerPath,CoreFixture.Key,f.Service.Remove,()=>{scheduled=true;Check(File.Exists(Path.Combine(f.Root,CoreDeployment.RecordName)),"schedule sees retained authenticated installation record");});
    if(kind=="modified")File.WriteAllText(f.Result.LauncherPath,"user change");
    if(kind=="pending")CoreUpdateTransaction.Stage(f.Root,CoreFixture.Manifest("1.2.4",new Dictionary<string,byte[]>(CoreFixture.A){{"卸载橙子启动器.exe",CoreFixture.Bytes("fixture uninstaller")}}),new Dictionary<string,byte[]>(),CoreFixture.Key);
    bool threw=false;if(kind=="locked"){using(var held=new FileStream(f.Result.LauncherPath,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){try{uninstall();}catch(IOException){threw=true;}}}else{try{uninstall();}catch(IOException){threw=true;}}
    if(kind=="success")Check(!threw&&scheduled&&!File.Exists(created.Path)&&warning.Contains("已删除")&&!File.Exists(f.Result.LauncherPath),"successful uninstall removes shortcut after core preflight while identity remains");else Check(threw&&!scheduled&&File.Exists(created.Path),kind+" uninstall preflight retains working owned shortcut");
   }
  }
  [STAThread] public static int Main(){try{
   LauncherRuntime.Initialize();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Control.CheckForIllegalCrossThreadCalls=true;boundary=FreshBoundary();captures=Path.Combine(boundary,"captures");Directory.CreateDirectory(captures);CoreFixture.Initialize();
   using(var form=new InstallerForm(new InstallerDestination{Root=Path.Combine(LauncherTestPaths.Root,"shortcut-ui-red")},(root,p)=>new InstallerInstallResult(root,AppVersion.Current,"fixture"),r=>{})){
    form.Show();Application.DoEvents();var option=form.Controls.Find("installer-desktop-shortcut",true).SingleOrDefault() as CheckBox;
    Check(option!=null&&option.Checked&&option.Text=="创建桌面快捷方式（当前用户）","interactive install offers default-checked current-user desktop shortcut before any installation");form.Close();
   }
   Check(typeof(InstallerForm).Assembly.GetType("PZ3D.InstallerShortcut")!=null,"authenticated isolated shortcut service exists");
   Ui();Service();Console.WriteLine("CAPTURES: "+captures);
   Console.WriteLine("INSTALLER SHORTCUT: "+passed+" PASS");return 0;
  }catch(Exception error){Console.WriteLine(error);return 1;}}
  static string FreshBoundary(){string root=Path.Combine(LauncherTestPaths.Root,"s4-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(root);return root;}
 }
}
